"""M11.d: photos made safe before storage or model input (SEC-05). Every image here is generated by the test."""

from __future__ import annotations

import io
import struct
import time
import tracemalloc
import zlib

import pytest
from agent_core.config import Settings
from agent_core.store.images import PhotoRejectedError, make_safe
from PIL import Image

SETTINGS = Settings()
GPS_IFD = 0x8825


def _photo_with_gps(size: tuple[int, int] = (3000, 2000)) -> bytes:
    image = Image.new("RGB", size, (200, 120, 40))
    exif = Image.Exif()
    exif[0x010F] = "Synthetic Phone Co"  # Make
    exif[0x0132] = "2026:10:11 12:00:00"  # DateTime
    exif[0x0112] = 6  # Orientation: rotate 90 degrees to show upright
    exif.get_ifd(GPS_IFD).update({1: "N", 2: (5.0, 33.0, 0.0), 3: "W", 4: (0.0, 12.0, 0.0)})
    out = io.BytesIO()
    image.save(out, "JPEG", exif=exif, quality=90)
    return out.getvalue()


def sec05_exif_stripped() -> None:
    original = _photo_with_gps()
    assert Image.open(io.BytesIO(original)).getexif().get_ifd(GPS_IFD)  # the fixture does carry a location
    safe = make_safe(original, SETTINGS)
    reopened = Image.open(io.BytesIO(safe.jpeg))
    assert reopened.format == "JPEG" and not reopened.getexif() and not reopened.info.get("exif")
    assert b"Exif\x00\x00" not in safe.jpeg and b"http://ns.adobe.com/xap/" not in safe.jpeg  # no EXIF or XMP
    assert "icc_profile" not in reopened.info
    # Turned upright from the orientation tag before it was dropped, then downscaled to the configured side.
    assert (safe.width, safe.height) == (SETTINGS.photo_downscale_side_px * 2000 // 3000,
                                         SETTINGS.photo_downscale_side_px)  # fmt: skip
    # A PNG without metadata passes through to a JPEG too; anything else is refused as an unsupported format.
    png = io.BytesIO()
    Image.new("RGB", (64, 48), (1, 2, 3)).save(png, "PNG")
    assert make_safe(png.getvalue(), SETTINGS).width == 64
    gif = io.BytesIO()
    Image.new("RGB", (8, 8)).save(gif, "GIF")
    with pytest.raises(PhotoRejectedError) as refused:
        make_safe(gif.getvalue(), SETTINGS)
    assert refused.value.code == "unsupported_format"


def _png_header_only(width: int, height: int) -> bytes:
    """A tiny PNG whose header claims `width` x `height` (a decompression bomb's shape)."""

    def chunk(kind: bytes, body: bytes) -> bytes:
        return struct.pack(">I", len(body)) + kind + body + struct.pack(">I", zlib.crc32(kind + body))

    header = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", zlib.compress(b"\x00" * 64)) + chunk(
        b"IEND", b"")  # fmt: skip


def sec05_image_bomb_rejected() -> None:
    for width, height in ((100_000, 100_000), (SETTINGS.photo_max_side_px + 1, 10), (20_000, 20_000)):
        bomb = _png_header_only(width, height)
        assert len(bomb) < 1024
        tracemalloc.start()
        started = time.monotonic()
        with pytest.raises(PhotoRejectedError) as refused:
            make_safe(bomb, SETTINGS)
        _, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert refused.value.code == "image_too_large", (width, height)
        assert peak < 16 * 1024 * 1024 and time.monotonic() - started < 2.0  # refused from the header alone
    # Over the byte cap: refused before anything is decoded.
    with pytest.raises(PhotoRejectedError) as refused:
        make_safe(b"\xff" * int(SETTINGS.photo_max_mb * 1024 * 1024 + 1), SETTINGS)
    assert refused.value.code == "image_too_large"
